CREATE TABLE `proyecto_almacen` (
  `id_proyecto_almacen` int NOT NULL,
  `tipo_movil` enum('CON_PROYECTO','SIN_PROYECTO') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Tipo de móvil',
  `id_referencia` int NOT NULL COMMENT 'ID de movil_proyecto o movil_persona',
  `id_empresa` int NOT NULL COMMENT 'FK a empresa',
  `id_bodega` int NOT NULL COMMENT 'FK a bodega',
  `id_reserva` int NOT NULL COMMENT 'FK a reserva',
  `codigo_proyecto` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Código único del proyecto',
  `nombre_proyecto` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Nombre del proyecto o persona',
  `descripcion` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `fecha_registro` date NOT NULL,
  `estado` enum('ACTIVO','INACTIVO') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'ACTIVO'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Tabla principal unificada de proyectos y personas';

