--
-- Disparadores `proyecto_almacen`
--
DELIMITER $$
CREATE TRIGGER `before_insert_proyecto_almacen` BEFORE INSERT ON `proyecto_almacen` FOR EACH ROW BEGIN
    IF NEW.codigo_proyecto IS NULL THEN
        SET NEW.codigo_proyecto = CONCAT(
            CASE NEW.tipo_movil
                WHEN 'CON_PROYECTO' THEN 'PRY'
                WHEN 'SIN_PROYECTO' THEN 'PER'
            END,
            '-',
            LPAD(NEW.id_empresa, 3, '0'),
            '-',
            DATE_FORMAT(NOW(), '%Y%m%d'),
            '-',
            LPAD(FLOOR(RAND() * 9999), 4, '0')
        );
    END IF;
END
$$
DELIMITER ;

