--
-- Estructura para la vista `vista_productos_con_subfamilia`
--
DROP TABLE IF EXISTS `vista_productos_con_subfamilia`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `vista_productos_con_subfamilia`  AS SELECT `p`.`codigo_producto` AS `codigo_producto`, `p`.`descripcion` AS `descripcion`, `p`.`unidad` AS `unidad`, `p`.`consumible` AS `consumible`, `p`.`tipo_producto` AS `tipo_producto`, `p`.`id_subfamilia` AS `id_subfamilia`, `s`.`nombre_subfamilia` AS `nombre_subfamilia`, `s`.`prefijo_sub` AS `prefijo_sub`, `fn`.`id_familia` AS `id_familia`, `fn`.`nombre_familia` AS `nombre_familia`, `fn`.`prefijo_codigo` AS `prefijo_codigo`, (case when (`p`.`id_subfamilia` is not null) then 'NUEVO' else 'ANTIGUO' end) AS `sistema_codigo` FROM ((`producto` `p` left join `subfamilia` `s` on((`p`.`id_subfamilia` = `s`.`id_subfamilia`))) left join `familia_nueva` `fn` on((`s`.`id_familia` = `fn`.`id_familia`))) ;

-- --------------------------------------------------------

--
-- Estructura para la vista `vista_proyectos_almacen`
--
DROP TABLE IF EXISTS `vista_proyectos_almacen`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `vista_proyectos_almacen`  AS SELECT `pa`.`id_proyecto_almacen` AS `id_proyecto_almacen`, `pa`.`tipo_movil` AS `tipo_movil`, `pa`.`id_referencia` AS `id_referencia`, `pa`.`id_empresa` AS `id_empresa`, `pa`.`id_bodega` AS `id_bodega`, `pa`.`id_reserva` AS `id_reserva`, `pa`.`codigo_proyecto` AS `codigo_proyecto`, `pa`.`nombre_proyecto` AS `nombre_proyecto`, `pa`.`descripcion` AS `descripcion`, `pa`.`fecha_registro` AS `fecha_registro`, `pa`.`estado` AS `estado`, `e`.`razon_social` AS `empresa_nombre`, `e`.`ruc` AS `empresa_ruc`, `b`.`nombre` AS `bodega_nombre`, `b`.`ubicacion` AS `bodega_ubicacion`, `r`.`tipo_reserva` AS `reserva_tipo`, `mp`.`nom_ape` AS `nom_ape`, `mp`.`dni` AS `dni`, `mp`.`ciudad` AS `ciudad`, `mp`.`observaciones` AS `observaciones`, `mp`.`firma` AS `firma` FROM ((((`proyecto_almacen` `pa` join `empresa` `e` on((`pa`.`id_empresa` = `e`.`id_empresa`))) join `bodega` `b` on((`pa`.`id_bodega` = `b`.`id_bodega`))) join `reserva` `r` on((`pa`.`id_reserva` = `r`.`id_reserva`))) left join `movil_persona` `mp` on(((`pa`.`tipo_movil` = 'SIN_PROYECTO') and (`pa`.`id_referencia` = `mp`.`id_movil_persona`)))) ;

